package main

import (
	"os"
	"path/filepath"
	"testing"
)

// This is how "DO NOT EDIT" is enforced: the committed types.go files must be
// exactly what the generator produces from the current catalog. A hand edit
// fails here, and so does a catalog change nobody regenerated.
func TestGeneratedFilesMatchTheCatalog(t *testing.T) {
	t.Parallel()
	root, err := moduleRoot()
	if err != nil {
		t.Fatalf("module root: %v", err)
	}
	want, _, err := generate(root)
	if err != nil {
		t.Fatalf("generate: %v", err)
	}
	if len(want) == 0 {
		t.Fatal("generated nothing; the catalog or the domain mapping is broken")
	}
	for path, src := range want {
		rel, _ := filepath.Rel(root, path)
		t.Run(rel, func(t *testing.T) {
			t.Parallel()
			got, err := os.ReadFile(path)
			if err != nil {
				t.Fatalf("%s is missing; run `make gen`", rel)
			}
			if string(got) != string(src) {
				t.Errorf("%s differs from what the catalog generates.\n"+
					"Either it was edited by hand (it says DO NOT EDIT), or "+
					"research/dtos.yaml changed and nobody ran `make gen`.", rel)
			}
		})
	}
}

// Every generated file has to carry the marker, or the rule above is unenforceable.
func TestGeneratedFilesCarryTheMarker(t *testing.T) {
	t.Parallel()
	root, err := moduleRoot()
	if err != nil {
		t.Fatalf("module root: %v", err)
	}
	files, _, err := generate(root)
	if err != nil {
		t.Fatalf("generate: %v", err)
	}
	for path, src := range files {
		rel, _ := filepath.Rel(root, path)
		// go/build's own convention for a generated file.
		if want := "// Code generated by tools/gen/server from research/dtos.yaml. DO NOT EDIT.\n"; len(src) < len(want) || string(src[:len(want)]) != want {
			t.Errorf("%s does not open with the generated-code marker", rel)
		}
	}
}
